```kotlin
enum class MapUpdateState { NOT_INSTALLED, INCOMPLETE, CURRENT,
    UPDATE_AVAILABLE, UNKNOWN }

fun mapUpdateState(
    row: OfflineRegionListRow,
    installed: List<OfflineInstalledRegion>
): MapUpdateState {
    val catalog = row.mapRegion ?: return MapUpdateState.UNKNOWN
    val local = installed.firstOrNull { it.regionId.toLong() == row.regionId }
        ?: return MapUpdateState.NOT_INSTALLED
    if (!local.allTarsOk) return MapUpdateState.INCOMPLETE
    val latest = catalog.version
    val current = local.regionVersion
    if (latest.isNullOrBlank() || current.isNullOrBlank()) {
        return MapUpdateState.UNKNOWN
    }
    return if (latest == current) MapUpdateState.CURRENT
           else MapUpdateState.UPDATE_AVAILABLE
}
```

