## Cache-first Screen Implementation

```kotlin
private var catalogReadToken = 0L
fun loadRegionCatalog(force: Boolean) {
    readCachedRegions()
    val mode = if (force) RegionListSyncMode.FORCE else RegionListSyncMode.AUTO
    NBNavigation.syncRegions(
        mode,
        object : NBNavigationTaskCallback<OfflineRegionCatalogSyncResult> {
            override fun onSuccess(result: OfflineRegionCatalogSyncResult?) {
                readCachedRegions()
            }
            override fun onError(throwable: Throwable) {
                readCachedRegions()
                showCatalogRefreshWarning(throwable)
            }
        }
    )
}
private fun readCachedRegions() {
    val token = ++catalogReadToken
    NBNavigation.fetchRegionLists(
        "United States",
        object : NBNavigationTaskCallback<OfflineRegionListResult> {
            override fun onSuccess(result: OfflineRegionListResult?) {
                if (token != catalogReadToken || result == null) return
                showRegions(result.regionRows.filter { it.hasRoute && it.hasMap })
                result.routeError?.let(::showRouteCatalogWarning)
                result.mapError?.let(::showMapCatalogWarning)
            }
            override fun onError(throwable: Throwable) {
                if (token == catalogReadToken) {
                    showOfflineError("Loading cached regions failed", throwable)
                }
            }
        }
    )
}
